# Find the last translation and add new ones before the closing brace
$lastClosing = $content.LastIndexOf("        };")
$beforeClosing = $content.Substring(0, $lastClosing - 1)  # Remove the last character (the newline before })
$afterClosing = $content.Substring($lastClosing - 1)  # Get from the newline onward

# Combine
$combined = $beforeClosing + "," + $newTranslations + "`n" + $afterClosing

[System.IO.File]::WriteAllText($file, $combined)
Write-Host "Added Arabic translations successfully"
